=== FILE: rr_arbiter.v ===
// rr_arbiter.v
// Round-robin arbiter for N requesters (default 4): at most one grant per
// cycle, combinational from req and the priority pointer.
// Implements microarchitecture.md for interface_spec.md (project
// prj-5e13e6856c, requirement req-142be1ce31).
`timescale 1ns / 1ps
`default_nettype none

module rr_arbiter #(
    parameter integer N = 4
) (
    input  wire         clk,
    input  wire         rst_n,
    input  wire [N-1:0] req,
    output reg  [N-1:0] grant
);

    // Pointer width. N must be 2 or more (interface spec, section 1).
    localparam integer  PW     = (N > 1) ? $clog2(N) : 1;
    localparam [31:0]   LAST_W = N - 1;
    localparam [31:0]   ONE_W  = 1;
    localparam [PW-1:0] LAST   = LAST_W[PW-1:0];
    localparam [PW-1:0] ONE    = ONE_W[PW-1:0];

    // State: the priority pointer (microarchitecture section 1).
    reg [PW-1:0] ptr;
    reg [PW-1:0] ptr_nxt;

    // Combinational search results.
    reg [PW-1:0] winner;
    reg          any_grant;
    reg [PW-1:0] idx;
    integer      i;

    // Wrapping priority search from ptr upwards (microarchitecture section 2).
    // Every output gets a default first, so no latch is inferred.
    always @* begin
        grant     = {N{1'b0}};
        winner    = {PW{1'b0}};
        any_grant = 1'b0;
        idx       = ptr;
        for (i = 0; i < N; i = i + 1) begin
            if (!any_grant && req[idx]) begin
                grant[idx] = 1'b1;
                winner     = idx;
                any_grant  = 1'b1;
            end
            if (idx == LAST) begin
                idx = {PW{1'b0}};
            end else begin
                idx = idx + ONE;
            end
        end
    end

    // Pointer update: one past the winner, wrapping at N; hold with no grant
    // (microarchitecture section 3).
    always @* begin
        ptr_nxt = ptr;
        if (any_grant) begin
            if (winner == LAST) begin
                ptr_nxt = {PW{1'b0}};
            end else begin
                ptr_nxt = winner + ONE;
            end
        end
    end

    // Synchronous active-low reset to pointer 0 (microarchitecture section 4).
    always @(posedge clk) begin
        if (!rst_n) begin
            ptr <= {PW{1'b0}};
        end else begin
            ptr <= ptr_nxt;
        end
    end

`ifdef FORMAL
    // ------------------------------------------------------------------
    // Design-intent properties (microarchitecture section 5).
    // ------------------------------------------------------------------
    reg f_past_valid;
    initial f_past_valid = 1'b0;
    always @(posedge clk) f_past_valid <= 1'b1;

    // Reset is active on the first cycle.
    always @(*) begin
        if (!f_past_valid) assume (!rst_n);
    end

    wire [PW:0]   f_win_ext = {1'b0, winner};
    wire [PW:0]   f_ptr_ext = {1'b0, ptr};
    // Distance from the pointer to the winner, searching upwards with wrap.
    wire [PW:0]   f_dist_w  = (f_win_ext >= f_ptr_ext) ? (f_win_ext - f_ptr_ext)
                                                       : (f_win_ext + N - f_ptr_ext);
    // Independent model of "one past the winner, wrapping at N".
    wire [PW:0]   f_win_inc = f_win_ext + 1'b1;
    wire [PW-1:0] f_next    = (f_win_inc == N) ? {PW{1'b0}} : f_win_inc[PW-1:0];

    always @(*) begin
        if (f_past_valid) begin
            // Pointer in range.
            assert (ptr <= LAST);
            // One-hot or zero.
            assert ((grant & (grant - 1'b1)) == {N{1'b0}});
            // Only to a requester.
            assert ((grant & ~req) == {N{1'b0}});
            // Work conserving.
            if (req != {N{1'b0}}) assert (any_grant);
            assert (any_grant == (grant != {N{1'b0}}));
            // The winner holds the grant and asks for it.
            if (any_grant) assert (grant[winner] && req[winner]);
        end
    end

    // Pointer: 0 after reset, one past the winner after a grant, else held.
    always @(posedge clk) begin
        if (f_past_valid) begin
            if (!$past(rst_n)) begin
                assert (ptr == {PW{1'b0}});
            end else if ($past(any_grant)) begin
                assert (ptr == $past(f_next));
            end else begin
                assert (ptr == $past(ptr));
            end
        end
    end

    genvar gk;
    generate
        for (gk = 0; gk < N; gk = gk + 1) begin : g_formal
            // Cycles requester gk has waited with its request held.
            reg  [PW:0] f_wait;
            // Distance from the pointer to requester gk.
            wire [PW:0] f_dist = (gk >= ptr) ? (gk - ptr) : (gk + N - ptr);

            always @(posedge clk) begin
                if (!rst_n || !req[gk] || grant[gk]) begin
                    f_wait <= {(PW+1){1'b0}};
                end else begin
                    f_wait <= f_wait + 1'b1;
                end
            end

            always @(*) begin
                if (f_past_valid) begin
                    // Starvation bound: at most N-1 cycles waited.
                    assert (f_wait <= LAST);
                    // Induction invariant: wait plus distance stays within N-1.
                    assert (f_wait + f_dist <= N - 1);
                    // Round-robin order: nobody asks between the pointer and the winner.
                    if (any_grant && (f_dist < f_dist_w)) assert (!req[gk]);
                end
                if (f_past_valid && rst_n) begin
                    cover (grant[gk]);
                    cover (grant[gk] && (f_wait == {1'b0, LAST}));
                end
            end
        end
    endgenerate

    always @(*) begin
        if (f_past_valid && rst_n) cover (req == {N{1'b1}});
        if (f_past_valid && !rst_n) cover (req != {N{1'b0}});
    end

    // The pointer wraps from N-1 to 0.
    always @(posedge clk) begin
        if (f_past_valid && $past(rst_n) && $past(any_grant)
            && ($past(winner) == LAST)) begin
            cover (ptr == {PW{1'b0}});
        end
    end
`endif

endmodule

`default_nettype wire
=== END FILE ===
