// rr_arbiter_tb.v
// Self-checking testbench for rr_arbiter: two arbiters side by side (N=4 and
// N=5), each checked every cycle against a reference pointer model, with
// per-requester fairness counters and coverage counters.
`timescale 1ns / 1ps
`default_nettype none

module rr_arbiter_tb;

    reg        clk;
    reg        rst_n;
    reg  [3:0] req4;
    reg  [4:0] req5;
    wire [3:0] grant4;
    wire [4:0] grant5;

    rr_arbiter #(.N(4)) u_arb4 (
        .clk   (clk),
        .rst_n (rst_n),
        .req   (req4),
        .grant (grant4)
    );

    rr_arbiter #(.N(5)) u_arb5 (
        .clk   (clk),
        .rst_n (rst_n),
        .req   (req5),
        .grant (grant5)
    );

    initial clk = 1'b0;
    always #5 clk = ~clk;

    integer        passed;
    integer        failed;
    integer        cyc;
    reg [8*64-1:0] nonce;
    reg [31:0]     lfsr;
    reg            model_valid;

    // Per-arbiter model and coverage state (index 0: N=4, index 1: N=5).
    integer   mptr        [0:1];
    integer   mwin        [0:1];
    integer   wcnt        [0:15];
    reg [7:0] prev_r      [0:1];
    reg       prev_rs     [0:1];
    reg       traffic     [0:1];
    reg [7:0] alone_seen  [0:1];
    integer   cov_none    [0:1];
    integer   cov_all     [0:1];
    integer   cov_held    [0:1];
    integer   cov_maxwait [0:1];
    integer   cov_rst     [0:1];

    integer ii;
    integer ci;
    integer rt;

    // Reference round-robin pick: first requester at or after p, wrapping at n.
    function integer rr_pick;
        input integer n;
        input [7:0]   r;
        input integer p;
        integer s;
        integer idx;
        begin
            rr_pick = -1;
            for (s = 0; s < n; s = s + 1) begin
                idx = (p + s) % n;
                if (rr_pick < 0 && ((r >> idx) & 8'd1) != 8'd0) rr_pick = idx;
            end
        end
    endfunction

    function bitof;
        input [7:0]   v;
        input integer b;
        begin
            bitof = ((v >> b) & 8'd1) != 8'd0;
        end
    endfunction

    task next_rand;
        integer s;
        begin
            for (s = 0; s < 8; s = s + 1)
                lfsr = {lfsr[30:0], lfsr[31] ^ lfsr[21] ^ lfsr[1] ^ lfsr[0]};
        end
    endtask

    // Check one arbiter's grant for the current cycle and update fairness
    // and coverage counters.
    task check_arb;
        input integer a;
        input integer n;
        input [7:0]   r;
        input [7:0]   g;
        input         rs;
        integer   kk;
        integer   base;
        reg [7:0] expg;
        reg [7:0] allm;
        begin
            base = a * 8;
            allm = (8'd1 << n) - 8'd1;
            mwin[a] = rr_pick(n, r, mptr[a]);
            if (mwin[a] >= 0) expg = 8'd1 << mwin[a];
            else              expg = 8'd0;
            if (g === expg) begin
                passed = passed + 1;
            end else begin
                failed = failed + 1;
                $error("N=%0d cycle %0d: req=%b ptr=%0d grant=%b, expected %b",
                       n, cyc, r, mptr[a], g, expg);
            end
            if (rs) begin
                for (kk = 0; kk < n; kk = kk + 1) begin
                    if (bitof(r, kk)) begin
                        if (bitof(g, kk)) begin
                            if (wcnt[base+kk] <= n - 1) begin
                                passed = passed + 1;
                            end else begin
                                failed = failed + 1;
                                $error("N=%0d cycle %0d: requester %0d granted after %0d cycles waiting",
                                       n, cyc, kk, wcnt[base+kk]);
                            end
                            if (wcnt[base+kk] == n - 1) cov_maxwait[a] = cov_maxwait[a] + 1;
                            wcnt[base+kk] = 0;
                        end else begin
                            wcnt[base+kk] = wcnt[base+kk] + 1;
                            if (wcnt[base+kk] > n - 1) begin
                                failed = failed + 1;
                                $error("N=%0d cycle %0d: requester %0d has waited %0d cycles",
                                       n, cyc, kk, wcnt[base+kk]);
                            end
                        end
                    end else begin
                        wcnt[base+kk] = 0;
                    end
                end
                if (r == 8'd0) cov_none[a] = cov_none[a] + 1;
                if (r == allm) cov_all[a] = cov_all[a] + 1;
                if (r != 8'd0 && (r & (r - 8'd1)) == 8'd0) alone_seen[a] = alone_seen[a] | r;
                if (prev_rs[a] && (prev_r[a] & r) != 8'd0 && (prev_r[a] ^ r) != 8'd0)
                    cov_held[a] = cov_held[a] + 1;
                if (r != 8'd0) traffic[a] = 1'b1;
            end else begin
                for (kk = 0; kk < n; kk = kk + 1) wcnt[base+kk] = 0;
                if (traffic[a] && r != 8'd0) cov_rst[a] = cov_rst[a] + 1;
            end
            prev_r[a]  = r;
            prev_rs[a] = rs;
        end
    endtask

    // Reference pointer update at a rising edge.
    task advance;
        input integer a;
        input integer n;
        input         rs;
        begin
            if (!rs)               mptr[a] = 0;
            else if (mwin[a] >= 0) mptr[a] = (mwin[a] + 1) % n;
        end
    endtask

    // Drive inputs at the falling edge, then check the combinational grant.
    task drive;
        input [3:0] r4;
        input [4:0] r5;
        input       rs;
        begin
            @(negedge clk);
            req4  = r4;
            req5  = r5;
            rst_n = rs;
            #1;
            if (model_valid) begin
                check_arb(0, 4, {4'b0000, req4}, {4'b0000, grant4}, rst_n);
                check_arb(1, 5, {3'b000, req5}, {3'b000, grant5}, rst_n);
            end
        end
    endtask

    task finish_cycle;
        begin
            @(posedge clk);
            if (model_valid || !rst_n) begin
                advance(0, 4, rst_n);
                advance(1, 5, rst_n);
            end
            if (!rst_n) model_valid = 1'b1;
            cyc = cyc + 1;
        end
    endtask

    task step;
        input [3:0] r4;
        input [4:0] r5;
        input       rs;
        begin
            drive(r4, r5, rs);
            finish_cycle;
        end
    endtask

    // Everyone requesting right after reset: grants rotate 0, 1, ..., N-1.
    task rot_phase;
        input integer cycles;
        begin
            for (rt = 0; rt < cycles; rt = rt + 1) begin
                drive(4'b1111, 5'b11111, 1'b1);
                if (grant4 === (4'd1 << (rt % 4))) begin
                    passed = passed + 1;
                end else begin
                    failed = failed + 1;
                    $error("N=4 rotation step %0d: grant=%b, expected %b",
                           rt, grant4, 4'd1 << (rt % 4));
                end
                if (grant5 === (5'd1 << (rt % 5))) begin
                    passed = passed + 1;
                end else begin
                    failed = failed + 1;
                    $error("N=5 rotation step %0d: grant=%b, expected %b",
                           rt, grant5, 5'd1 << (rt % 5));
                end
                finish_cycle;
            end
        end
    endtask

    task expect_cov;
        input               ok;
        input integer       n;
        input [8*40-1:0]    what;
        begin
            if (ok) begin
                passed = passed + 1;
            end else begin
                failed = failed + 1;
                $error("N=%0d coverage: %0s not reached", n, what);
            end
        end
    endtask

    task cover_check;
        input integer a;
        input integer n;
        reg [7:0] allm;
        begin
            allm = (8'd1 << n) - 8'd1;
            expect_cov(cov_none[a] > 0,       n, "no requests");
            expect_cov(alone_seen[a] == allm, n, "each requester alone");
            expect_cov(cov_all[a] > 0,        n, "everyone requesting");
            expect_cov(cov_held[a] > 0,       n, "held request among changing others");
            expect_cov(cov_maxwait[a] > 0,    n, "longest fair wait (N-1)");
            expect_cov(cov_rst[a] > 0,        n, "reset during traffic");
        end
    endtask

    initial begin
        passed      = 0;
        failed      = 0;
        cyc         = 0;
        model_valid = 1'b0;
        lfsr        = 32'h1ACE_B00C;
        req4        = 4'b0000;
        req5        = 5'b00000;
        rst_n       = 1'b0;
        for (ii = 0; ii < 16; ii = ii + 1) wcnt[ii] = 0;
        for (ii = 0; ii < 2; ii = ii + 1) begin
            mptr[ii]        = 0;
            mwin[ii]        = -1;
            prev_r[ii]      = 8'd0;
            prev_rs[ii]     = 1'b0;
            traffic[ii]     = 1'b0;
            alone_seen[ii]  = 8'd0;
            cov_none[ii]    = 0;
            cov_all[ii]     = 0;
            cov_held[ii]    = 0;
            cov_maxwait[ii] = 0;
            cov_rst[ii]     = 0;
        end
        if (!$value$plusargs("nirmaan_nonce=%s", nonce)) nonce = "unset";

        // 1. Reset with no requests, then a reset cycle with requests
        //    (grant follows req during reset; pointer stays 0).
        step(4'b0000, 5'b00000, 1'b0);
        step(4'b0000, 5'b00000, 1'b0);
        step(4'b0110, 5'b10100, 1'b0);

        // 2. Everyone requesting after reset: strict rotation and the
        //    longest fair wait (N-1 cycles).
        rot_phase(20);

        // 3. No requests.
        for (ci = 0; ci < 3; ci = ci + 1) step(4'b0000, 5'b00000, 1'b1);

        // 4. Each requester alone.
        for (ci = 0; ci < 10; ci = ci + 1)
            step(4'd1 << (ci % 4), 5'd1 << (ci % 5), 1'b1);

        // 5. A held request among changing others.
        for (ci = 0; ci < 40; ci = ci + 1) begin
            next_rand;
            step(lfsr[3:0] | 4'b0100, lfsr[8:4] | 5'b01000, 1'b1);
        end

        // 6. Random subsets: requests dropped and raised again.
        for (ci = 0; ci < 300; ci = ci + 1) begin
            next_rand;
            step(lfsr[3:0], lfsr[8:4], 1'b1);
        end

        // 7. Reset during traffic, then strict rotation again.
        step(4'b1111, 5'b11111, 1'b1);
        step(4'b1111, 5'b11111, 1'b1);
        step(4'b1011, 5'b11011, 1'b1);
        step(4'b1111, 5'b11111, 1'b0);
        step(4'b0101, 5'b10101, 1'b0);
        rot_phase(20);

        // 8. Random traffic with occasional resets.
        for (ci = 0; ci < 200; ci = ci + 1) begin
            next_rand;
            step(lfsr[3:0], lfsr[8:4], lfsr[15:12] != 4'd0);
        end

        // 9. Idle.
        step(4'b0000, 5'b00000, 1'b1);
        step(4'b0000, 5'b00000, 1'b1);

        cover_check(0, 4);
        cover_check(1, 5);

        $display("NIRMAAN-SIM %0s %0d passed, %0d failed", nonce, passed, failed);
        $finish;
    end

endmodule

`default_nettype wire
